1	// E8 order fulfilment with compensation (SPEC-E). A pure function of (input, ctx): time is input.now only.
2	// Each tick replays the events into the carry, then drives every rule whose window is open.
3	
4	const MIN = 60000;
5	const TERM = ['completed', 'failed', 'cancelled'];
6	const INVALID = ['invalid-args', 'field-renamed'];
7	const MEANINGS = ['collected', 'inTransit', 'delivered', 'collectionFailed', 'info'];
8	const MAX_TRIES = 5;
9	
10	export function createSolver() {
11	  return { id: 'solver', tick: (input, ctx) => tick(input, ctx) };
12	}
13	
14	function tick(input, ctx) {
15	  const now = Date.parse(input.now);
16	  const T = { now, ctx, fx: [], up: [], cancel: [], ht: [], merge: null, close: false, memo: {} };
17	  const ev = input.events || [];
18	  let c = input.carry ? JSON.parse(JSON.stringify(input.carry)) : null;
19	  if (!c) {
20	    const early = route(T, input, ev);
21	    if (early) return early;
22	    const start = ev.find(e => e.type === 'order.placed' || e.type === 'migration');
23	    if (!start) return out(T, null, null);
24	    c = (start.type === 'migration' && fromRecords(T, start)) || newCarry(T, start);
25	    if (!c.o) { T.close = true; return out(T, null, null); }
26	  }
27	  // Carrier reports first: a collection in the same instant as a cancel wins (S4).
28	  for (const e of ev) if (e.type === 'carrier.status') handle(T, c, e);
29	  for (const e of ev) if (e.type !== 'carrier.status') handle(T, c, e);
30	  drive(T, c);
31	  if (c.ph === 'end' && !pending(c)) {
32	    T.close = true;
33	    T.cancel.push(...c.ob);
34	    c.ob = [];
35	  }
36	  return out(T, c, c.o);
37	}
38	
39	// ---------- helpers ----------
40	
41	export function norm(raw) {
42	  if (raw === null || raw === undefined) return null;
43	  let s = String(raw).trim();
44	  if (s.startsWith('#')) s = s.slice(1).trim();
45	  return s.toUpperCase();
46	}
47	
48	// Amsterdam-local ISO string with offset, minute precision.
49	function isoAms(t) {
50	  const d = new Date(t);
51	  const f = new Intl.DateTimeFormat('en-GB', {
52	    timeZone: 'Europe/Amsterdam', hourCycle: 'h23', year: 'numeric', month: '2-digit',
53	    day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit',
54	  });
55	  const p = Object.fromEntries(f.formatToParts(d).map(x => [x.type, x.value]));
56	  const local = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second);
57	  const off = Math.round((local - t) / MIN);
58	  const a = Math.abs(off);
59	  const sign = off < 0 ? '-' : '+';
60	  return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}${sign}${String(Math.floor(a / 60)).padStart(2, '0')}:${String(a % 60).padStart(2, '0')}`;
61	}
62	
63	function localDay(t) {
64	  return new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Amsterdam', year: 'numeric', month: '2-digit', day: '2-digit' })
65	    .format(new Date(t));
66	}
67	
68	function fileOf(ctx, path) {
69	  const f = ctx.files;
70	  if (!f) return undefined;
71	  const flat = f instanceof Map ? f.get(path) : f[path];
72	  if (flat !== undefined) return flat;
73	  let v = f;
74	  for (const seg of path.split('/')) {
75	    if (v === null || v === undefined) return undefined;
76	    v = v instanceof Map ? v.get(seg) : v[seg];
77	  }
78	  return v;
79	}
80	
81	function listOf(ctx, dir) {
82	  const f = ctx.files;
83	  if (!f) return [];
84	  const keys = f instanceof Map ? [...f.keys()] : Object.keys(f);
85	  const names = new Set();
86	  for (const k of keys) if (k.startsWith(dir + '/')) names.add(k.slice(dir.length + 1).split('/')[0]);
87	  if (!names.size) {
88	    const sub = fileOf(ctx, dir);
89	    if (sub && typeof sub === 'object' && !Array.isArray(sub)) return Object.keys(sub);
90	  }
91	  return [...names];
92	}
93	
94	function load(ctx, path) {
95	  const v = fileOf(ctx, path);
96	  if (v === undefined || v === null) return undefined;
97	  if (typeof v !== 'string') return v;
98	  if (path.endsWith('.csv')) return parseCsv(v);
99	  try { return JSON.parse(v); } catch { return undefined; }
100	}
101	
102	function parseCsv(text) {
103	  const lines = text.split(/\r?\n/).filter(l => l.trim() !== '');
104	  if (!lines.length) return [];
105	  const head = lines[0].split(',').map(h => h.trim());
106	  return lines.slice(1).map(l => {
107	    const cells = l.split(',').map(x => x.trim());
108	    const row = {};
109	    head.forEach((h, i) => {
110	      const v = cells[i];
111	      row[h] = v !== undefined && v !== '' && !isNaN(Number(v)) ? Number(v) : v;
112	    });
113	    return row;
114	  });
115	}
116	
117	function rowsOf(doc) {
118	  if (Array.isArray(doc)) return doc;
119	  if (doc && typeof doc === 'object') for (const v of Object.values(doc)) if (Array.isArray(v)) return v;
120	  return [];
121	}
122	
123	function field(row, names) {
124	  if (!row || typeof row !== 'object') return undefined;
125	  for (const n of names) if (row[n] !== undefined) return row[n];
126	  const keys = Object.keys(row);
127	  for (const n of names) {
128	    const hit = keys.find(k => k.toLowerCase() === n.toLowerCase());
129	    if (hit !== undefined) return row[hit];
130	  }
131	  return undefined;
132	}
133	
134	function findKey(o, k) {
135	  if (!o || typeof o !== 'object') return undefined;
136	  if (o[k] !== undefined) return o[k];
137	  for (const v of Object.values(o)) {
138	    const r = findKey(v, k);
139	    if (r !== undefined) return r;
140	  }
141	  return undefined;
142	}
143	
144	function editionAt(ctx, t) {
145	  const day = localDay(t);
146	  const eds = [];
147	  for (const d of listOf(ctx, 'rulebook')) {
148	    const e = load(ctx, `rulebook/${d}/edition.json`);
149	    if (e && e.effectiveFrom) eds.push({ dir: d, from: String(e.effectiveFrom).slice(0, 10) });
150	  }
151	  const ok = eds.filter(e => e.from <= day).sort((a, b) => (a.from < b.from ? 1 : -1));
152	  return ok.length ? ok[0].dir : null;
153	}
154	
155	function policy(T, c, name) {
156	  const v = findKey(load(T.ctx, `rulebook/${c.ed}/policy.json`), name);
157	  return Number(v) || 0;
158	}
159	
160	function priceOf(T, sku) {
161	  if (!T.memo.cat) T.memo.cat = rowsOf(load(T.ctx, 'master/catalog.json'));
162	  const r = T.memo.cat.find(x => String(field(x, ['sku'])) === sku);
163	  return Number(field(r, ['unitPriceMinor', 'unitPrice', 'priceMinor'])) || 0;
164	}
165	
166	function feeOf(T, c, loc) {
167	  if (!loc) return 0;
168	  const rows = rowsOf(load(T.ctx, `rulebook/${c.ed}/shipping-fees.json`));
169	  const r = rows.find(x => String(field(x, ['location'])) === loc);
170	  return Number(field(r, ['feeMinor', 'fee'])) || 0;
171	}
172	
173	function emailOf(T, customerId) {
174	  const rows = rowsOf(load(T.ctx, 'master/customers.json'));
175	  const r = rows.find(x => String(field(x, ['customerId'])) === String(customerId));
176	  return field(r, ['email']) || customerId;
177	}
178	
179	function meaningOf(T, c, code) {
180	  const rows = rowsOf(load(T.ctx, `rulebook/${c.ed}/carrier-codes.json`));
181	  for (const r of rows) {
182	    const k = field(r, ['code', 'carrierCode']);
183	    if (k !== undefined && String(k) === String(code)) {
184	      const m = field(r, ['meaning', 'status', 'means', 'kind']);
185	      if (MEANINGS.includes(String(m))) return String(m);
186	    }
187	  }
188	  return 'info';
189	}
190	
191	function openOf(T, subject) {
192	  const list = T.ctx.instances({ subject }) || [];
193	  return list.map(x => (typeof x === 'string' ? x : x.instance ?? x.id)).filter(Boolean);
194	}
195	
196	function queryRows(T, table, where) {
197	  const r = T.ctx.query(table, { where });
198	  return Array.isArray(r) ? r : (r && r.rows) || [];
199	}
200	
201	function errCode(err) {
202	  if (!err) return '';
203	  return typeof err === 'string' ? err : err.code || '';
204	}
205	
206	function isInvalid(err) {
207	  return INVALID.includes(errCode(err)) || (err && typeof err === 'object' && err.status === 400);
208	}
209	
210	function pending(c) {
211	  return Object.values(c.k).some(v => v[3] === 'pend');
212	}
213	
214	const STEP_TAGS = ['rsv', 'chg', 'shp', 'shpc', 'ref', 'rel'];
215	
216	function stepPending(c, fid) {
217	  return Object.values(c.k).some(v => v[1] === fid && STEP_TAGS.includes(v[0]) && v[3] === 'pend');
218	}
219	
220	// ---------- routing of the first tick ----------
221	
222	function route(T, input, ev) {
223	  const e = ev.find(x => ['order.placed', 'customer.action', 'carrier.status'].includes(x.type)) || ev[0];
224	  const done = (subject, extra) => ({ decisions: { subject }, effects: [], obligations: { upsert: [], cancel: [] }, humanTasks: [], carry: {}, ...extra });
225	  if (!e || e.type === 'migration') return null;
226	  if (e.type === 'order.placed') {
227	    const o = norm(e.payload && e.payload.orderId);
228	    const open = openOf(T, o).filter(i => i !== input.instance);
229	    if (open.length) return done(o, { merge: { into: open[0] } });
230	    if (queryRows(T, 'orders.orders', { orderId: o }).length) return done(o, { close: true });
231	    return null;
232	  }
233	  if (e.type === 'customer.action') {
234	    const o = norm(e.payload && e.payload.orderRef);
235	    const open = openOf(T, o).filter(i => i !== input.instance);
236	    if (open.length) return done(o, { merge: { into: open[0] } });
237	    const known = queryRows(T, 'orders.orders', { orderId: o }).length > 0;
238	    return done(known ? o : null, { close: true });
239	  }
240	  if (e.type === 'carrier.status') {
241	    const fid = String((e.payload && e.payload.fulfilmentRef) || '').trim();
242	    const o = (queryRows(T, 'orders.fulfilments', { fulfilmentId: fid })[0] || {}).orderId ?? null;
243	    const open = o ? openOf(T, o).filter(i => i !== input.instance) : [];
244	    if (open.length) return done(o, { merge: { into: open[0] } });
245	    return done(o, { close: true });
246	  }
247	  return done(null, { close: true });
248	}
249	
250	// ---------- carry ----------
251	
252	function newCarry(T, e) {
253	  // Migration payloads may nest the order fields, so look each one up anywhere in the payload.
254	  const pl = (e && e.payload) || {};
255	  const p = (k) => findKey(pl, k);
256	  const o = norm(p('orderId'));
257	  const placed = p('placedAt') || e.at;
258	  const ed = editionAt(T.ctx, placed);
259	  const c = {
260	    o, p: placed, cu: p('customerId'), cur: p('currency'), it: p('items') || [], ed,
261	    R: 0, A: 0, em: null, al: null, fd: null, rec: 'no', fr: null, cl: null,
262	    ph: 'intake', D: null, act: null, ost: 'pending', stop: null, f: {}, k: {}, tries: {}, ob: [],
263	  };
264	  c.R = policy(T, c, 'fraudReviewHours');
265	  c.A = policy(T, c, 'customerActionHours');
266	  c.em = emailOf(T, c.cu);
267	  return c;
268	}
269	
270	// ---------- events ----------
271	
272	function handle(T, c, e) {
273	  const at = Date.parse(e.at);
274	  // An effect.result carries its fields at top level or inside payload; accept either.
275	  if (e.type === 'effect.result') return result(T, c, Object.assign({}, e, e.payload || {}));
276	  if (e.type === 'customer.action') return action(T, c, e, at);
277	  if (e.type === 'carrier.status') return carrier(T, c, e, at);
278	  if (e.type && e.type.startsWith('humanTask.') && c.fr) return task(T, c, e, at);
279	}
280	
281	// The batch reserve is unkeyed (its items carry the keys), so it is tracked per fulfilment.
282	function batchKey(c, e) {
283	  const its = Array.isArray(e.items) ? e.items : [];
284	  const hit = its.find(x => x && typeof x.key === 'string' && x.key.startsWith(`${c.o}:ri:`));
285	  if (hit) return `~inventory.reserve|${hit.key.slice(c.o.length + 4).split(':')[0]}`;
286	  const pend = Object.keys(c.k).filter(k => k.startsWith('~inventory.reserve|') && c.k[k][3] === 'pend');
287	  return pend.length === 1 ? pend[0] : '';
288	}
289	
290	function result(T, c, e) {
291	  // Unkeyed effects are matched by system.op, whatever key the platform echoes back.
292	  let kk = c.k[e.key] ? e.key : `~${e.system}.${e.op}`;
293	  if (e.op === 'reserve') kk = batchKey(c, e);
294	  const m = c.k[kk];
295	  if (!m) return;
296	  const [tag, fid, sub] = m;
297	  const f = fid ? c.f[fid] : null;
298	  const ok = e.status === 'ok';
299	  const code = errCode(e.error);
300	  if (!ok && tag !== 'rsv' && (tag === 'alloc' || tag === 'fraud' || tag === 'create' || isInvalid(e.error))) {
301	    c.tries[tag] = (c.tries[tag] || 0) + 1;
302	    if (c.tries[tag] <= MAX_TRIES) { delete c.k[kk]; return; }
303	  }
304	  m[3] = ok ? 'ok' : 'err';
305	  const body = e.items ?? e.result ?? e.output ?? e.value;
306	  switch (tag) {
307	    case 'alloc':
308	      if (ok) plan(T, c, body);
309	      return;
310	    case 'fraud': {
311	      const v = body && typeof body === 'object' ? (body.verdict ?? body) : body;
312	      c.fd = v === 'pass' ? 'pass' : v === 'reject' ? 'reject' : 'review';
313	      if (c.fd === 'pass') c.cl = c.p;
314	      if (c.fd === 'reject') c.stop = 'fraud';
315	      return;
316	    }
317	    case 'create':
318	      if (ok) c.rec = 'ok';
319	      return;
320	    case 'rsv':
321	      rsvResult(c, f, e);
322	      // Items still to submit: drop the batch entry so the next drive resubmits them with their own keys.
323	      if (f.items.some(it => f.rsv[it.sku] === 'no')) delete c.k[kk];
324	      return;
325	    case 'chg':
326	      if (ok) f.chg = 'ok';
327	      else f.chg = code === 'card-declined' || (e.error && e.error.status === 402) ? 'declined' : 'bad';
328	      return;
329	    case 'shp':
330	      f.shp = ok ? 'ok' : 'bad';
331	      return;
332	    case 'shpc':
333	      f.shpc = ok ? 'ok' : 'refused';
334	      return;
335	    case 'ref':
336	      f.ref = ok ? 'ok' : 'bad';
337	      return;
338	    case 'rel':
339	      f.rel[sub] = ok ? 'ok' : 'bad';
340	      return;
341	    default:
342	      return;
343	  }
344	}
345	
346	function plan(T, c, items) {
347	  const rows = Array.isArray(items) ? items : (items && items.fulfilments) || [];
348	  c.f = {};
349	  for (const r of rows) {
350	    const fid = String(r.fulfilmentId);
351	    const avail = r.location !== null && r.location !== undefined && r.available !== false;
352	    const loc = avail ? String(r.location) : null;
353	    const its = (r.items || []).map(i => ({ sku: String(i.sku), qty: Number(i.qty) }));
354	    const amt = its.reduce((s, i) => s + i.qty * priceOf(T, i.sku), 0) + feeOf(T, c, loc);
355	    c.f[fid] = {
356	      id: fid, loc, avail, items: its, amt, st: avail ? 'pending' : 'unavailable',
357	      rsv: Object.fromEntries(its.map(i => [i.sku, 'no'])), rel: {},
358	      chg: 'no', shp: 'no', shpc: 'no', ref: 'no', coll: null, cd: false, cf: false, dl: false, fail: false,
359	    };
360	  }
361	  c.al = Object.keys(c.f);
362	}
363	
364	function rsvResult(c, f, e) {
365	  const n = (c.tries['rsv' + f.id] = (c.tries['rsv' + f.id] || 0) + 1);
366	  for (const it of f.items) {
367	    if (f.rsv[it.sku] === 'ok') continue;
368	    const ik = `${c.o}:ri:${f.id}:${it.sku}`;
369	    const r = Array.isArray(e.items) ? e.items.find(x => x && x.key === ik) : undefined;
370	    if (e.status === 'ok' || (r && r.status === 'ok')) { f.rsv[it.sku] = 'ok'; continue; }
371	    const rc = r ? r.error : e.error;
372	    // Items the batch did not process committed nothing: resubmit them with their original keys.
373	    const retry = isInvalid(rc) || errCode(rc) === 'batch-item-not-processed'
374	      || (!r && e.status === 'partial') || (r && !rc && r.status === 'partial');
375	    f.rsv[it.sku] = retry && n <= MAX_TRIES ? 'no' : 'bad';
376	  }
377	}
378	
379	function action(T, c, e, at) {
380	  const pl = e.payload || {};
381	  if (c.ph === 'intake') {
382	    if (pl.action === 'cancel' && !c.stop) c.stop = 'customer';
383	    return;
384	  }
385	  if (c.ph === 'wait' && !c.act && at <= Date.parse(c.D)) {
386	    c.act = pl.action === 'amend' ? 'amend' : 'cancel';
387	    if (c.act === 'cancel') c.stop = 'customer';
388	    return;
389	  }
390	  if (c.ph === 'proc' && pl.action === 'cancel' && !c.stop) {
391	    const refused = Object.values(c.f).some(f => f.coll !== null && f.coll <= at);
392	    if (refused) {
393	      return notify(T, c, 'cancel-refused', null, c.em, 'Your order can no longer be cancelled: it has been collected for shipping.');
394	    }
395	    c.stop = 'customer';
396	  }
397	}
398	
399	function carrier(T, c, e, at) {
400	  const p = e.payload || {};
401	  const f = c.f[String(p.fulfilmentRef || '').trim()];
402	  if (!f || TERM.includes(f.st) || f.st === 'unavailable') return;
403	  const mean = meaningOf(T, c, p.code);
404	  const t = Date.parse(p.reportedAt || e.at) || at;
405	  if (['collected', 'inTransit', 'delivered'].includes(mean)) {
406	    f.coll = f.coll === null ? t : Math.min(f.coll, t);
407	    if (mean !== 'inTransit') f.cd = true;
408	    if (mean === 'delivered') f.dl = true;
409	  } else if (mean === 'collectionFailed' && f.coll === null) {
410	    f.cf = true;
411	    f.fail = true;
412	  }
413	}
414	
415	function task(T, c, e, at) {
416	  // A rejected or withdrawn task is asked again (same deadline); timeout and delegation change nothing here.
417	  if (e.type === 'humanTask.answerRejected' || e.type === 'humanTask.withdrawn') {
418	    c.fr.redo = true;
419	    return;
420	  }
421	  if (e.type !== 'humanTask.answered') return;
422	  const pl = e.payload || {};
423	  const raw = pl.answer !== undefined ? pl.answer : pl;
424	  const d = typeof raw === 'string' ? raw : raw && raw.decision;
425	  if (!c.fr.ans && c.fd === 'review' && (d === 'approve' || d === 'reject') && at <= c.fr.due) {
426	    c.fr.ans = { d, at };
427	    if (d === 'approve') c.cl = isoAms(at);
428	    else c.stop = 'fraud';
429	  } else if (!c.fr.ans) {
430	    c.fr.redo = true;
431	  }
432	}
433	
434	// ---------- effects ----------
435	
436	// Field names follow the live api schema in ctx.files (a system may rename a field mid-run).
437	const norm2 = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
438	const tokens = s => String(s).replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
439	
440	function renamedTo(props, k, args) {
441	  const have = Object.keys(props);
442	  const free = have.filter(h => !(h in args));
443	  const byNorm = free.find(h => norm2(h) === norm2(k));
444	  if (byNorm) return byNorm;
445	  const byNote = free.find(h => [].concat(props[h].renamedFrom || [], props[h].formerly || []).includes(k));
446	  if (byNote) return byNote;
447	  const kt = tokens(k);
448	  let best = null;
449	  let bestScore = 0;
450	  for (const h of free) {
451	    const ht = tokens(h);
452	    const score = kt.filter(t => ht.includes(t)).length;
453	    if (score > bestScore) { best = h; bestScore = score; }
454	  }
455	  return best;
456	}
457	
458	function adapt(T, system, op, args) {
459	  const sch = load(T.ctx, `api/${system}.schema.json`);
460	  const a = sch && sch.ops && sch.ops[op] && sch.ops[op].args;
461	  if (!a || !a.properties) return args;
462	  const props = a.properties;
463	  const out = {};
464	  for (const [k, v] of Object.entries(args)) {
465	    if (k in props) out[k] = v;
466	    else {
467	      const nk = renamedTo(props, k, out);
468	      out[nk || k] = v;
469	    }
470	  }
471	  const itp = props.items && props.items.items && props.items.items.properties;
472	  if (Array.isArray(out.items) && itp) {
473	    out.items = out.items.map(it => {
474	      const r = {};
475	      for (const [k, v] of Object.entries(it)) {
476	        if (k in itp) r[k] = v;
477	        else r[renamedTo(itp, k, r) || k] = v;
478	      }
479	      return r;
480	    });
481	  }
482	  return out;
483	}
484	
485	function send(T, c, tag, fid, sub, system, op, args, keyed = true) {
486	  const key = keyed ? `${c.o}:${tag}:${fid || '-'}:${sub || '-'}` : `~${system}.${op}`;
487	  if (c.k[key]) return false;
488	  const e = { system, op, args: adapt(T, system, op, args) };
489	  if (keyed) e.key = key;
490	  T.fx.push(e);
491	  c.k[key] = [tag, fid || null, sub || null, 'pend'];
492	  return true;
493	}
494	
495	function setOrd(T, c, status) {
496	  if (c.ost === status) return;
497	  c.ost = status;
498	  send(T, c, 'os', null, status, 'orders', 'setStatus', { orderId: c.o, fulfilmentId: null, status });
499	}
500	
501	function setF(T, c, f, status) {
502	  if (f.st === status || TERM.includes(f.st)) return;
503	  f.st = status;
504	  send(T, c, 'fs', f.id, status, 'orders', 'setStatus', { orderId: c.o, fulfilmentId: f.id, status });
505	}
506	
507	function notify(T, c, template, fid, to, text) {
508	  return send(T, c, 'n', fid, template, 'notify', 'send', {
509	    to, about: fid || c.o, template, text,
510	  });
511	}
512	
513	// ---------- the driver ----------
514	
515	function drive(T, c) {
516	  const { now } = T;
517	  if (c.al === null) send(T, c, 'alloc', null, null, 'inventory', 'allocate', { orderId: c.o }, false);
518	  if (c.fd === null) send(T, c, 'fraud', null, null, 'fraud', 'check', { orderId: c.o }, false);
519	  if (c.al && c.rec === 'no') {
520	    const fs = Object.values(c.f);
521	    send(T, c, 'create', null, null, 'orders', 'create', {
522	      orderId: c.o, customerId: c.cu, placedAt: c.p, currency: c.cur, items: c.it,
523	      fulfilments: fs.map(f => ({ fulfilmentId: f.id, location: f.loc, items: f.items, amountMinor: f.amt })),
524	      totalMinor: fs.reduce((s, f) => s + f.amt, 0),
525	    });
526	  }
527	  if (c.rec !== 'ok') return;
528	
529	  // R2 fraud review
530	  if (c.fd === 'review' && !c.fr && !c.stop) {
531	    c.fr = { n: 1, emitted: 0, due: now + c.R * 60 * MIN, ans: null, redo: false };
532	  }
533	  if (c.fr && !c.fr.ans && c.fd === 'review' && !c.stop) {
534	    if (now > c.fr.due) c.stop = 'fraud-review-timeout';
535	    else {
536	      if (c.fr.redo) { c.fr.n += 1; c.fr.redo = false; }
537	      if (c.fr.emitted < c.fr.n) {
538	        c.fr.emitted = c.fr.n;
539	        T.ht.push({
540	          id: `${c.o}:fr${c.fr.n}`, kind: 'fraudReview', role: 'fraudAnalyst', subject: c.o,
541	          question: `Review order ${c.o} and answer approve or reject.`,
542	          answerSchema: { type: 'object', required: ['decision'], properties: { decision: { enum: ['approve', 'reject'] } } },
543	          dueAt: isoAms(c.fr.due), onTimeout: 'fraudReviewTimeout',
544	        });
545	      }
546	      obligation(T, c, `${c.o}:fr`, c.fr.due + MIN, 'fraudReviewDeadline');
547	    }
548	  }
549	
550	  // R2/R3 clearing
551	  if (c.cl && c.ph === 'intake' && !c.stop) {
552	    const unav = Object.values(c.f).some(f => !f.avail);
553	    if (unav) {
554	      c.ph = 'wait';
555	      c.D = isoAms(Date.parse(c.p) + c.A * 60 * MIN);
556	      setOrd(T, c, 'customerActionRequired');
557	      notify(T, c, 'action-required', null, c.em, 'Some items of your order are unavailable. Please amend or cancel within the deadline.');
558	    } else {
559	      ready(T, c);
560	    }
561	  }
562	
563	  // R3.2 waiting for the customer
564	  if (c.ph === 'wait') {
565	    if (c.act === 'amend') {
566	      for (const f of Object.values(c.f)) if (!f.avail) setF(T, c, f, 'cancelled');
567	      if (!Object.values(c.f).some(f => f.avail)) c.stop = 'nothing-available';
568	      else ready(T, c);
569	    } else if (!c.act && now > Date.parse(c.D)) {
570	      for (const f of Object.values(c.f)) setF(T, c, f, 'cancelled');
571	      setOrd(T, c, 'timedOut');
572	      notify(T, c, 'order-timed-out', null, c.em, 'Your order timed out and was not shipped.');
573	      c.ph = 'end';
574	    } else if (!c.act) {
575	      obligation(T, c, `${c.o}:cust`, Date.parse(c.D) + MIN, 'customerDeadline');
576	    }
577	  }
578	  if (c.ph === 'end') return;
579	
580	  // R6 stop: compensate every fulfilment not yet terminal
581	  if (c.stop) {
582	    if (c.ost !== 'cancelled') {
583	      setOrd(T, c, 'cancelled');
584	      notify(T, c, 'order-cancelled', null, c.em, `Your order was cancelled (${c.stop}).`);
585	    }
586	    for (const f of Object.values(c.f)) {
587	      if (TERM.includes(f.st)) continue;
588	      if (compensate(T, c, f)) setF(T, c, f, 'cancelled');
589	    }
590	    if (Object.values(c.f).every(f => TERM.includes(f.st))) c.ph = 'end';
591	    return;
592	  }
593	
594	  if (c.ph !== 'proc') return;
595	  for (const f of Object.values(c.f)) {
596	    if (!f.avail || TERM.includes(f.st)) continue;
597	    saga(T, c, f);
598	    if (f.fail) {
599	      if (compensate(T, c, f)) { setF(T, c, f, 'failed'); failNotice(T, c, f); }
600	      continue;
601	    }
602	    if (f.cd && f.st === 'processing') setF(T, c, f, 'dispatched');
603	    if (f.dl && f.st === 'dispatched') setF(T, c, f, 'completed');
604	  }
605	  const fs = Object.values(c.f);
606	  if (fs.every(f => TERM.includes(f.st))) {
607	    const st = fs.some(f => f.st === 'completed') ? 'completed' : fs.some(f => f.st === 'failed') ? 'failed' : 'cancelled';
608	    setOrd(T, c, st);
609	    c.ph = 'end';
610	  }
611	}
612	
613	function ready(T, c) {
614	  c.ph = 'proc';
615	  setOrd(T, c, 'processing');
616	  for (const f of Object.values(c.f)) if (f.avail) setF(T, c, f, 'processing');
617	}
618	
619	function failNotice(T, c, f) {
620	  notify(T, c, 'fulfilment-failed', f.id, c.em, `Fulfilment ${f.id} failed and was refunded.`);
621	}
622	
623	function obligation(T, c, id, dueMs, onDue) {
624	  if (c.ob.includes(id)) return;
625	  c.ob.push(id);
626	  T.up.push({ id, kind: 'deadline', anchor: c.p, dueAt: isoAms(dueMs), onDue });
627	}
628	
629	// R4.2 steps of one fulfilment, each only after the previous one committed.
630	function saga(T, c, f) {
631	  if (stepPending(c, f.id)) return;
632	  const need = f.items.filter(it => f.rsv[it.sku] === 'no');
633	  if (need.length) {
634	    const kk = `~inventory.reserve|${f.id}`;
635	    if (!c.k[kk]) {
636	      T.fx.push({
637	        system: 'inventory', op: 'reserve', args: adapt(T, 'inventory', 'reserve', {
638	          orderId: c.o, fulfilmentId: f.id, location: f.loc,
639	          items: need.map(it => ({ key: `${c.o}:ri:${f.id}:${it.sku}`, sku: it.sku, qty: it.qty })),
640	        }),
641	      });
642	      c.k[kk] = ['rsv', f.id, null, 'pend'];
643	    }
644	    return;
645	  }
646	  if (f.items.some(it => f.rsv[it.sku] === 'bad')) { f.fail = true; return; }
647	  if (f.chg === 'no') {
648	    send(T, c, 'chg', f.id, null, 'billing', 'charge', {
649	      orderId: c.o, fulfilmentId: f.id, customerId: c.cu, amountMinor: f.amt, currency: c.cur,
650	    });
651	    return;
652	  }
653	  if (f.chg === 'declined' || f.chg === 'bad') { f.fail = true; return; }
654	  if (f.shp === 'no') {
655	    send(T, c, 'shp', f.id, null, 'carrier', 'create', { orderId: c.o, fulfilmentId: f.id, location: f.loc, ref: f.id });
656	    return;
657	  }
658	  if (f.shp === 'bad') f.fail = true;
659	}
660	
661	// R5.1 compensation in reverse order. Returns true once nothing is left to undo.
662	function compensate(T, c, f) {
663	  if (stepPending(c, f.id)) return false;
664	  if (f.shp === 'ok' && f.shpc === 'no') {
665	    if (f.coll !== null || f.cf) f.shpc = f.cf ? 'na' : 'refused';
666	    else send(T, c, 'shpc', f.id, null, 'carrier', 'cancel', { orderId: c.o, fulfilmentId: f.id });
667	    if (f.shpc === 'no') return false;
668	  }
669	  if (f.shp !== 'ok' && f.shpc === 'no') f.shpc = 'na';
670	  if (f.chg === 'ok' && f.ref === 'no') {
671	    send(T, c, 'ref', f.id, null, 'billing', 'refund', { orderId: c.o, fulfilmentId: f.id, amountMinor: f.amt });
672	    return false;
673	  }
674	  if (f.chg !== 'ok' && f.ref === 'no') f.ref = 'na';
675	  for (const it of f.items) {
676	    if (f.rsv[it.sku] === 'ok' && !f.rel[it.sku]) f.rel[it.sku] = 'no';
677	  }
678	  for (const it of f.items) {
679	    if (f.rel[it.sku] === 'no') {
680	      send(T, c, 'rel', f.id, it.sku, 'inventory', 'release', { orderId: c.o, fulfilmentId: f.id, sku: it.sku });
681	      return false;
682	    }
683	  }
684	  return true;
685	}
686	
687	// ---------- go-live (migration): rebuild the carry from the records that exist ----------
688	
689	function fromRecords(T, e) {
690	  const o = norm(findKey(e.payload, 'orderId'));
691	  const ord = o ? queryRows(T, 'orders.orders', { orderId: o })[0] : null;
692	  if (!ord) return null;
693	  const c = newCarry(T, { at: ord.placedAt || e.at, payload: { orderId: o, customerId: ord.customerId, currency: ord.currency, items: ord.items, placedAt: ord.placedAt } });
694	  const rows = queryRows(T, 'orders.fulfilments', { orderId: o });
695	  const res = queryRows(T, 'inventory.reservations', { orderId: o });
696	  const charges = queryRows(T, 'billing.charges', { orderId: o });
697	  const refunds = queryRows(T, 'billing.refunds', { orderId: o });
698	  const ships = queryRows(T, 'carrier.shipments', { orderId: o });
699	  const placedMs = Date.parse(c.p);
700	  for (const r of rows) {
701	    const fid = String(r.fulfilmentId);
702	    const avail = r.location !== null && r.location !== undefined;
703	    const its = (r.items || []).map(i => ({ sku: String(i.sku), qty: Number(i.qty) }));
704	    const f = {
705	      id: fid, loc: avail ? String(r.location) : null, avail, items: its, amt: Number(r.amountMinor) || 0, st: r.status,
706	      rsv: Object.fromEntries(its.map(i => [i.sku, 'no'])), rel: {},
707	      chg: 'no', shp: 'no', shpc: 'no', ref: 'no', coll: null, cd: false, cf: false, dl: false, fail: false,
708	    };
709	    for (const x of res.filter(x => x.fulfilmentId === fid)) {
710	      if (x.status === 'active' && f.rsv[x.sku] !== undefined) f.rsv[x.sku] = 'ok';
711	      if (x.status === 'released' && f.rsv[x.sku] !== undefined) { f.rsv[x.sku] = 'ok'; f.rel[x.sku] = 'ok'; }
712	    }
713	    const ch = charges.find(x => x.fulfilmentId === fid);
714	    if (ch) f.chg = 'ok';
715	    if (ch && refunds.some(x => x.fulfilmentId === fid)) f.ref = 'ok';
716	    const sh = ships.find(x => x.fulfilmentId === fid);
717	    if (sh) {
718	      f.shp = 'ok';
719	      if (sh.status === 'cancelled') f.shpc = 'ok';
720	      if (['collected', 'inTransit', 'delivered'].includes(sh.status)) f.coll = placedMs;
721	      if (['collected', 'delivered'].includes(sh.status)) f.cd = true;
722	      if (sh.status === 'delivered') f.dl = true;
723	    }
724	    c.f[fid] = f;
725	  }
726	  c.al = Object.keys(c.f);
727	  c.rec = 'ok';
728	  c.ost = ord.status;
729	  if (ord.status === 'pending') return c;
730	  c.fd = 'pass';
731	  c.cl = c.p;
732	  if (ord.status === 'customerActionRequired') {
733	    c.ph = 'wait';
734	    c.D = isoAms(placedMs + c.A * 60 * MIN);
735	  } else if (ord.status === 'processing') {
736	    c.ph = 'proc';
737	  } else {
738	    c.ph = 'end';
739	  }
740	  return c;
741	}
742	
743	// ---------- output ----------
744	
745	function out(T, c, subject) {
746	  const o = { decisions: { subject }, effects: T.fx, obligations: { upsert: T.up, cancel: T.cancel }, humanTasks: T.ht, carry: c || {} };
747	  if (T.merge) o.merge = { into: T.merge };
748	  if (T.close) o.close = true;
749	  return o;
750	}
